17:  function comparison() {
18:    let left = sum();
19:    while (['<', '<=', '>', '>=', '==', '!='].includes(current().value)) {
20:      const operator = take();
21:      left = binary(operator, left, sum());
22:    }
23:    return left;
24:  }
