26:  function sum() {
27:    let left = product();
28:    while (is('+') || is('-')) {
29:      const operator = take();
30:      left = binary(operator, left, product());
31:    }
32:    return left;
33:  }
34:
35:  function product() {
36:    let left = power();
37:    while (['*', '/', '//', '%'].includes(current().value)) {
38:      const operator = take();
39:      left = binary(operator, left, power());
40:    }
41:    return left;
42:  }
43:
44:  function unary() {
45:    if (is('+') || is('-')) {
46:      return { type: 'unary', operator: take(), operand: unary() };
47:    }
48:    return primary();
49:  }
50:
51:  function power() {
52:    let left = unary();
53:    while (is('**')) {
54:      const operator = take();
55:      left = binary(operator, left, unary());
56:    }
57:    return left;
58:  }
