  function comparison() {
    const first = sum();
    if (!['<', '<=', '>', '>=', '==', '!='].includes(current().value)) return first;
    const operands = [first];
    const operators = [];
    while (['<', '<=', '>', '>=', '==', '!='].includes(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (['*', '/', '//', '%'].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  function unary() {
    if (is('+') || is('-')) {
      return { type: 'unary', operator: take(), operand: unary() };
    }
    return power();
  }

  function power() {
    const left = primary();
    if (!is('**')) return left;
    const operator = take();
    return binary(operator, left, unary());
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
