const { ExprError } = require('./errors');

/** Python float_rem: the result takes the divisor's sign; zero is positive. */
function modulo(left, right) {
  let mod = left % right;
  if (mod !== 0 && (right < 0) !== (mod < 0)) mod += right;
  return mod === 0 ? 0 : mod;
}

/** Python float_divmod's quotient, so a == (a // b) * b + a % b holds; zero is positive. */
function floorDivide(left, right) {
  const mod = left % right;
  let div = (left - mod) / right;
  if (mod !== 0 && (right < 0) !== (mod < 0)) div -= 1;
  if (div === 0) return 0;
  let floor = Math.floor(div);
  if (div - floor > 0.5) floor += 1;
  return floor === 0 ? 0 : floor;
}

